// Explicit behavioral contracts for every ability accessible to Gen1–5 species.
// No catalog-name-only or lifecycle check counts as a behavioral contract.
const assert=require('node:assert/strict'),e=require('../../server/game/battle/battleEngine'),a=require('../../server/game/abilities/abilityEngine'),forms=require('../../server/game/abilities/abilityForms');
const cases=new Map();let sequence=0;
const mon=(ability=null,extra={})=>Object.assign({uuid:'contract-'+(++sequence),name:'Test',truename:'Test',data:{id:143,type:['Normal'],base:{HP:80,Attack:80,Defense:80,'Sp. Attack':80,'Sp. Defense':80,Speed:80}},type1:'Normal',type2:null,level:50,maxHp:400,currentHp:400,attack:100,defense:100,specialAttack:100,specialDefense:100,speed:100,currentAttack:100,currentDefense:100,currentSpecialAttack:100,currentSpecialDefense:100,currentSpeed:100,status:'normal',gender:'male',passiveAbility:ability,heldItem:null,abilities:['Pound'],movePp:[35]},extra);
const rng=(n,f)=>{const old=Math.random;Math.random=()=>n;try{return f();}finally{Math.random=old;}};
const state=()=>e.createBattleState({battleType:'trainer'}),data=p=>e.ensureBattleData(p),stage=(p,s)=>data(p).statStages[s]||0;
function hit(p,d,move='Pound',s=state(),opts={}){return e.useattack(move,p,d,{battleState:s,attackerSide:s.sides.player,defenderSide:s.sides.enemy,attackerTeam:[p],defenderTeam:[d],consumePp:false,...opts});}
function entry(p,d=mon(),s=state()){return e.applySwitchInEffects(p,s.sides.player,s.sides.enemy,s,d);}
function end(p,d=mon(),s=state()){return e.processEndOfRound(p,d,s.sides.player,s.sides.enemy,s);}
function add(names,label,f){for(const n of names.split('|')){if(cases.has(n))throw Error('Duplicate contract '+n);cases.set(n,{name:n,label,run:()=>rng(.8,()=>f(n))});}}
const dmg=(ability,move,extra={},def={})=>hit(mon(ability,extra),mon(null,def),move).damage;
add('Adaptability','same-type attack gains extra STAB',n=>assert(dmg(n,'Pound')>dmg(null,'Pound')));
add('Aftermath','only a contact KO costs one quarter of attacker max HP',n=>{const p=mon();hit(p,mon(n,{currentHp:1}));assert.equal(p.currentHp,300);const q=mon();hit(q,mon(n,{currentHp:1}),'Water Gun');assert.equal(q.currentHp,400);});
add('Air Lock|Cloud Nine','opponent weather ability speed bonus is suppressed',n=>{const s=state();s.weather={kind:'rain',turns:5};assert.equal(a.getAbilitySpeedMultiplier(mon('Swift Swim'),s,mon(n)),1);assert.equal(a.getAbilitySpeedMultiplier(mon('Swift Swim'),s,mon()),2);});
add('Analytic','damage rises after the opposing action',n=>assert(hit(mon(n),mon(),'Pound',state(),{movedLast:true}).damage>dmg(null,'Pound')));
add('Anger Point','critical damage maximizes Attack',n=>rng(0,()=>{const p=mon(n);hit(mon(),p);assert.equal(stage(p,'attack'),6);}));
add('Anticipation','entry detects a super-effective threat',n=>{const p=mon(n,{type1:'Water'});assert(entry(p,mon(null,{abilities:['Thunderbolt']})).some(m=>m.includes('Anticipation')));});
add('Arena Trap|Magnet Pull|Shadow Tag','trapping rules are queried by the actual switch validator',n=>{const p=mon(null,{type1:n==='Magnet Pull'?'Steel':'Normal'}),op=mon(n);assert.equal(e.canSwitchOut(p,op,state()),false);});
add('Bad Dreams','sleeping enemy loses one eighth at end of turn',n=>{const d=mon(null,{status:'sleep'});end(mon(n),d);assert.equal(d.currentHp,350);const awake=mon();end(mon(n),awake);assert.equal(awake.currentHp,400);});
add('Battle Armor|Shell Armor','critical hits are blocked',n=>rng(0,()=>assert(!hit(mon(),mon(n)).critical)));
add('Big Pecks|Clear Body|Hyper Cutter|Keen Eye|White Smoke','appropriate opponent stat drop is prevented',n=>{const stat=n==='Big Pecks'?'defense':n==='Keen Eye'?'accuracy':'attack',p=mon(n);e.applyStageChange(p,stat,-1,[],mon());assert.equal(stage(p,stat),0);});
add('Blaze|Overgrow|Swarm|Torrent','low-health matching-type damage boost',n=>{const move={Blaze:'Ember',Overgrow:'Vine Whip',Swarm:'Bug Bite',Torrent:'Water Gun'}[n];assert(dmg(n,move,{currentHp:100})>dmg(n,move));});
add('Chlorophyll|Swift Swim|Sand Rush|Slush Rush','matching weather doubles Speed',n=>{const s=state();s.weather={kind:{Chlorophyll:'sun','Swift Swim':'rain','Sand Rush':'sandstorm','Slush Rush':'hail'}[n],turns:5};assert.equal(e.getBattleSpeed(mon(n),null,s),200);assert.equal(e.getBattleSpeed(mon(n),null,state()),100);});
add('Color Change','a damaging hit changes subsequent type',n=>{const p=mon(n);hit(mon(),p,'Water Gun');assert.deepEqual(data(p).tempTypes,['Water']);});
add('Competitive|Defiant','opposing drop triggers the appropriate +2 retaliation',n=>{const p=mon(n);e.applyStageChange(p,'defense',-1,[],mon());assert.equal(stage(p,n==='Competitive'?'specialAttack':'attack'),2);});
add('Compound Eyes|Victory Star','accuracy multiplier improves',n=>assert(a.getAbilityAccuracyMultiplier(mon(n),mon(),e.getMoveByName('Pound'),state())>1));
add('Contrary|Simple','stage changes are reversed or doubled',n=>{const p=mon(n);e.applyStageChange(p,'attack',1,[],p);assert.equal(stage(p,'attack'),n==='Contrary'?-1:2);});
add('Cursed Body','a damaging hit can disable the move',n=>rng(.1,()=>{const p=mon();hit(p,mon(n));assert.equal(data(p).disabledMove,'Pound');assert(data(p).disableTurns>0);}));
add('Cute Charm','opposite-gender contact can cause attraction',n=>rng(.1,()=>{const p=mon();hit(p,mon(n,{gender:'female'}));assert(data(p).infatuationTurns>0);}));
add('Damp','self-destruct fails before damage and sacrifice',n=>{const p=mon();const d=mon(n);hit(p,d,'Self-Destruct');assert(p.currentHp>0);assert.equal(d.currentHp,400);});
add('Defeatist','Attack drops at half HP',n=>assert(dmg(n,'Pound',{currentHp:200})<dmg(n,'Pound')));
add('Download','entry selects physical Attack when Defense is lower',n=>{const p=mon(n);entry(p,mon(null,{currentDefense:50,currentSpecialDefense:100}));assert.equal(stage(p,'attack'),1);});
add('Drizzle|Drought|Sand Stream|Snow Warning','entry sets the matching native weather',n=>{const s=state();entry(mon(n),mon(),s);assert.equal(s.weather.kind,{'Drizzle':'rain','Drought':'sun','Sand Stream':'sandstorm','Snow Warning':'hail'}[n]);});
add('Dry Skin|Volt Absorb|Water Absorb','matching incoming attack heals without causing damage',n=>{const p=mon(n,{currentHp:200});const r=hit(mon(),p,n==='Volt Absorb'?'Thunderbolt':'Water Gun');assert.equal(r.damage,0);assert.equal(p.currentHp,300);});
add('Early Bird','sleep counter expires twice as fast',n=>{const p=mon(n,{status:'sleep'});data(p).sleepTurns=2;hit(p,mon());assert.equal(p.status,'normal');});
add('Effect Spore|Flame Body|Poison Point|Static','contact status actually procs',n=>rng(.25,()=>{const p=mon();hit(p,mon(n));assert.equal(p.status,{Static:'paralyze','Flame Body':'burn','Poison Point':'poison','Effect Spore':'paralyze'}[n]);}));
add('Filter|Solid Rock','super-effective damage is reduced',n=>{const d={type1:'Rock'};assert(hit(mon(),mon(n,d),'Water Gun').damage<hit(mon(),mon(null,d),'Water Gun').damage);});
add('Flare Boost|Guts|Toxic Boost','status boosts the appropriate damage class',n=>{const move=n==='Flare Boost'?'Water Gun':'Pound',extra={status:n==='Toxic Boost'?'poison':'burn'};assert(dmg(n,move,extra)>dmg(null,move,extra));});
add('Flash Fire','absorbing Fire activates a later Fire boost',n=>{const p=mon(n);hit(mon(),p,'Ember');assert(data(p).flashFireBoost);assert(hit(p,mon(),'Ember').damage>dmg(null,'Ember'));});
add('Flower Gift','sun raises both Attack and Special Defense',n=>{const s=state();s.weather={kind:'sun',turns:5};assert.equal(a.getAbilityStatMultiplier(mon(n),'attack',s),1.5);assert.equal(a.getAbilityStatMultiplier(mon(n),'specialDefense',s),1.5);});
add('Forecast','Castform becomes Water in rain and returns when rain is suppressed',n=>{const p=require('../../scripts/calibrateCorruptionRaids').make(351,50,1,['Weather Ball'],n),s=state();s.weather={kind:'rain',turns:5};forms.syncWeatherForms(p,mon(),s);assert.deepEqual(data(p).formTypes,['Water']);forms.syncWeatherForms(p,mon('Cloud Nine'),s);assert(!data(p).formTypes);});
add('Forewarn|Frisk','entry reveals the relevant move or item',n=>{const hints=entry(mon(n),mon(null,{heldItem:'leftovers',abilities:['Pound','Hyper Beam']}));assert(hints.some(m=>m.includes(n==='Frisk'?'leftovers':'Hyper Beam')));});
add('Gluttony','low-health berry activates already at half HP',n=>{const p=mon(n,{heldItem:'liechi_berry',currentHp:190});hit(mon(),p);assert.equal(stage(p,'attack'),1);assert(!p.heldItem);});
add('Harvest','consumed berry can be restored in sun',n=>{const p=mon(n),s=state();data(p).consumedHeldItem='sitrus_berry';s.weather={kind:'sun',turns:5};end(p,mon(),s);assert.equal(p.heldItem,'sitrus_berry');});
add('Heatproof|Thick Fat','Fire damage is reduced',n=>assert(hit(mon(),mon(n),'Ember').damage<hit(mon(),mon(),'Ember').damage));
add('Heavy Metal|Light Metal','weight-dependent damage changes with actual weight',n=>{const p=mon(n),q=mon();p.data.id=q.data.id=54;const changed=hit(mon(),p,'Low Kick').damage,base=hit(mon(),q,'Low Kick').damage;assert(n==='Heavy Metal'?changed>base:changed<base);});
add('Huge Power|Pure Power|Hustle','physical attacks become stronger',n=>rng(.1,()=>assert(dmg(n,'Pound')>dmg(null,'Pound'))));
add('Hydration|Poison Heal|Rain Dish|Ice Body','end-of-turn recovery uses status or weather',n=>{const p=mon(n,{currentHp:200}),s=state();if(n==='Poison Heal')p.status='poison';if(n==='Hydration'){p.status='burn';s.weather={kind:'rain',turns:5};}if(n==='Rain Dish')s.weather={kind:'rain',turns:5};if(n==='Ice Body')s.weather={kind:'hail',turns:5};end(p,mon(),s);assert(n==='Hydration'?p.status==='normal':p.currentHp>200);});
add('Illusion','appearance is copied from the last healthy teammate, then breaks on a real hit',n=>{const p=mon(n),other=mon(null,{name:'Other'});forms.attachTeam([p,other]);forms.prepareIllusion(p);assert(data(p).illusion);hit(mon(),p);assert.equal(data(p).illusion,null);});
add('Immunity|Insomnia|Limber|Magma Armor|Vital Spirit|Water Veil','appropriate major status cannot be inflicted',n=>{const status={Immunity:'poison',Insomnia:'sleep',Limber:'paralyze','Magma Armor':'freeze','Vital Spirit':'sleep','Water Veil':'burn'}[n],p=mon(n);assert(!e.applyStatus(p,status,null,[]));assert.equal(p.status,'normal');});
add('Imposter','entry copies the opponent moves and stats without copying HP',n=>{const p=require('../../scripts/calibrateCorruptionRaids').make(132,50,1,['Transform'],n),d=require('../../scripts/calibrateCorruptionRaids').make(6,50,1,['Ember'],'Blaze'),hp=p.maxHp;entry(p,d);assert(data(p).transformed);assert.deepEqual(p.abilities,d.abilities);assert.equal(p.maxHp,hp);});
add('Infiltrator','substitute does not intercept the hit',n=>{const p=mon();data(p).substituteHp=100;assert(hit(mon(n),p).damage>0);assert.equal(data(p).substituteHp,100);});
add('Inner Focus|Shield Dust','move secondary flinch is prevented',n=>rng(.1,()=>{const p=mon(n);hit(mon(),p,'Fake Out');assert(!data(p).flinch);}));
add('Intimidate','entry lowers enemy Attack',n=>{const d=mon();entry(mon(n),d);assert.equal(stage(d,'attack'),-1);});
add('Iron Barbs|Rough Skin','contact attacker loses one eighth HP',n=>{const p=mon();hit(p,mon(n));assert.equal(p.currentHp,350);});
add('Iron Fist','punch damage rises and ranged damage does not',n=>{assert(dmg(n,'Fire Punch')>dmg(null,'Fire Punch'));assert.equal(dmg(n,'Water Gun'),dmg(null,'Water Gun'));});
add('Justified|Rattled|Weak Armor','relevant hit modifies the appropriate stat',n=>{const p=mon(n);hit(mon(),p,n==='Weak Armor'?'Pound':'Bite');assert.equal(stage(p,n==='Justified'?'attack':'speed'),n==='Weak Armor'?2:1);});
add('Klutz','held damage item is inactive',n=>assert.equal(dmg(n,'Water Gun',{heldItem:'choice_specs'}),dmg(null,'Water Gun')));
add('Leaf Guard','major status blocked in ordinary sun',n=>{const p=mon(n),s=state();s.weather={kind:'sun',turns:5};assert(!e.applyStatus(p,'poison',null,[],{battleState:s,attacker:mon()}));});
add('Levitate','Ground damage fails but a Ground status move still works',n=>{const p=mon(n);assert.equal(hit(mon(),p,'Earthquake').damage,0);hit(mon(),p,'Sand Attack');assert.equal(stage(p,'accuracy'),-1);});
add('Lightning Rod|Motor Drive|Sap Sipper|Storm Drain','absorption grants the correct stat boost',n=>{const p=mon(n),move=n==='Sap Sipper'?'Vine Whip':n==='Storm Drain'?'Water Gun':'Thunderbolt';assert.equal(hit(mon(),p,move).damage,0);assert.equal(stage(p,n==='Motor Drive'?'speed':n==='Sap Sipper'?'attack':'specialAttack'),1);});
add('Liquid Ooze','draining damages the attacker instead of healing',n=>{const p=mon(null,{currentHp:200});hit(p,mon(n),'Giga Drain');assert(p.currentHp<200);});
add('Magic Bounce','targeted status is reflected',n=>{const p=mon(),d=mon(n);hit(p,d,'Toxic');assert.equal(d.status,'normal');assert.equal(p.status,'badly_poison');});
add('Magic Guard','poison residual damage is prevented',n=>{const p=mon(n,{status:'poison'});end(p);assert.equal(p.currentHp,400);});
add('Marvel Scale','major status raises physical defense',n=>assert(hit(mon(),mon(n,{status:'poison'})).damage<hit(mon(),mon(null,{status:'poison'})).damage));
add('Mold Breaker|Teravolt|Turboblaze','Ground attacks bypass Levitate',n=>assert(hit(mon(n),mon('Levitate'),'Earthquake').damage>0));
add('Moody','end of turn raises one stat and lowers a different one',n=>{const p=mon(n);end(p);assert(Object.values(data(p).statStages).includes(2));assert(Object.values(data(p).statStages).includes(-1));});
add('Moxie','a damaging KO raises Attack',n=>{const p=mon(n);hit(p,mon(null,{currentHp:1}));assert.equal(stage(p,'attack'),1);});
add('Multiscale','reduction only at full HP',n=>assert(hit(mon(),mon(n)).damage<hit(mon(),mon(n,{currentHp:399})).damage));
add('Multitype','plate changes Arceus type',n=>{const p=require('../../scripts/calibrateCorruptionRaids').make(493,50,1,['Pound'],n);p.heldItem='flame_plate';forms.sync(p,'entry');assert.deepEqual(data(p).formTypes,['Fire']);});
add('Mummy','contact replaces a removable attacker ability',n=>{const p=mon('Guts');hit(p,mon(n));assert.equal(p.passiveAbility,'Mummy');});
add('Natural Cure|Regenerator','voluntary switch heals status or HP',n=>{const p=mon(n,{currentHp:200,status:'poison'});a.applySwitchOutAbility(p);assert(n==='Natural Cure'?p.status==='normal':p.currentHp>200);});
add('No Guard','an inaccurate attack cannot miss',n=>rng(.99,()=>assert(!hit(mon(n),mon(),'Dynamic Punch').missed)));
add('Normalize','non-Normal move is converted and cannot hit Ghost',n=>assert.equal(dmg(n,'Water Gun',{}, {type1:'Ghost'}),0));
add('Oblivious|Own Tempo','attraction or confusion is blocked',n=>{const p=mon(n);assert(!e.applyStatus(p,n==='Own Tempo'?'confusion':'infatuation',null,[]));});
add('Overcoat','powder status and hail are prevented',n=>{const p=mon(n),s=state();s.weather={kind:'hail',turns:5};hit(mon(),p,'Spore',s);assert.equal(p.status,'normal');end(p,mon(),s);assert.equal(p.currentHp,400);});
add('Pickpocket','surviving contact steals the attacker item',n=>{const p=mon(null,{heldItem:'expert_belt'}),d=mon(n);hit(p,d);assert.equal(d.heldItem,'expert_belt');assert(!p.heldItem);});
add('Pickup','consumed item is recovered from this same turn',n=>{const p=mon(n),d=mon(),s=state();Object.assign(data(d),{consumedHeldItem:'sitrus_berry',consumedHeldItemTurn:s.turn});end(p,d,s);assert.equal(p.heldItem,'sitrus_berry');});
add('Poison Touch','attacker contact poisons the defender',n=>rng(.1,()=>{const d=mon();hit(mon(n),d);assert.equal(d.status,'poison');}));
add('Prankster','status move priority increases',n=>assert.equal(e.getMovePriority('Growl',mon(n)),1));
add('Pressure','target costs an extra PP',n=>{const p=mon();hit(p,mon(n),'Pound',state(),{consumePp:true});assert.equal(p.movePp[0],33);});
add('Protean','executed attack changes user type',n=>{const p=mon(n);hit(p,mon(),'Water Gun');assert.deepEqual(data(p).tempTypes,['Water']);});
add('Quick Feet','status boosts Speed without paralysis penalty',n=>assert(e.getBattleSpeed(mon(n,{status:'paralyze'}))>e.getBattleSpeed(mon(null,{status:'paralyze'}))));
add('Reckless','recoil move damage rises',n=>assert(dmg(n,'Double-Edge')>dmg(null,'Double-Edge')));
add('Rivalry','same-gender physical damage rises',n=>assert(dmg(n,'Pound')>dmg(null,'Pound')));
add('Rock Head','move recoil is prevented',n=>{const p=mon(n);hit(p,mon(),'Double-Edge');assert.equal(p.currentHp,400);});
add('Run Away','escape ignores trapping but respects battle escape prohibition',n=>{const p=mon(n),q=mon(),s=state();data(p).trappedTurns=data(q).trappedTurns=3;assert(e.canSwitchOut(p,mon('Shadow Tag'),s,{escape:true}));assert(!e.canSwitchOut(q,mon('Shadow Tag'),s,{escape:true}));s.escapeForbidden=true;assert(!e.canSwitchOut(p,mon(),s,{escape:true}));});
add('Sand Force','matching damage rises only under sand',n=>{const s=state();s.weather={kind:'sandstorm',turns:5};assert(hit(mon(n),mon(),'Rock Throw',s).damage>dmg(n,'Rock Throw'));});
add('Sand Veil|Snow Cloak','matching weather lowers incoming accuracy',n=>{const s=state();s.weather={kind:n==='Sand Veil'?'sandstorm':'hail',turns:5};assert(a.getAbilityAccuracyMultiplier(mon(),mon(n),e.getMoveByName('Pound'),s)<1);});
add('Scrappy','Normal damage reaches a Ghost',n=>assert(dmg(n,'Pound',{}, {type1:'Ghost'})>0));
add('Serene Grace','secondary chance is doubled',n=>rng(.15,()=>{const d=mon();hit(mon(n),d,'Thunderbolt');assert.equal(d.status,'paralyze');const control=mon();hit(mon(),control,'Thunderbolt');assert.equal(control.status,'normal');}));
add('Shed Skin','end of turn can cure a major status',n=>rng(.1,()=>{const p=mon(n,{status:'poison'});end(p);assert.equal(p.status,'normal');}));
add('Sheer Force','secondary damage boost removes the secondary effect',n=>rng(.1,()=>{const d=mon();const r=hit(mon(n),d,'Thunderbolt');assert(r.damage>dmg(null,'Thunderbolt'));assert.equal(d.status,'normal');}));
add('Skill Link','a variable multi-hit move always hits five times',n=>assert.equal(hit(mon(n),mon(),'Double Slap').hits,5));
add('Slow Start','first five turns halve physical Attack and Speed',n=>{const p=mon(n);assert.equal(e.getBattleSpeed(p),50);assert(dmg(n,'Pound')<dmg(null,'Pound'));data(p).activeTurns=5;assert.equal(e.getBattleSpeed(p),100);});
add('Sniper','critical damage increases',n=>rng(0,()=>assert(dmg(n,'Pound')>dmg(null,'Pound'))));
add('Solar Power','sun boosts Special Attack and costs end-turn HP',n=>{const p=mon(n),s=state();s.weather={kind:'sun',turns:5};assert(hit(p,mon(),'Water Gun',s).damage>hit(mon(),mon(),'Water Gun',s).damage);end(p,mon(),s);assert.equal(p.currentHp,350);});
add('Soundproof','sound move cannot cause damage',n=>assert.equal(hit(mon(),mon(n),'Hyper Voice').damage,0));
add('Speed Boost','end turn adds one Speed stage',n=>{const p=mon(n);end(p);assert.equal(stage(p,'speed'),1);});
add('Stall','ordering penalty is applied by the turn planner',n=>{const p=mon(n,{speed:200,currentSpeed:200}),q=mon(),s=state();const sorted=e.orderBattleActions([{pokemon:p,moveName:'Pound'},{pokemon:q,moveName:'Pound'}],s);assert.equal(sorted[0].pokemon,q);});
add('Steadfast','being flinched raises Speed',n=>rng(.1,()=>{const p=mon(n);hit(mon(),p,'Fake Out');assert.equal(stage(p,'speed'),1);assert(data(p).flinch);}));
add('Stench','an eligible damaging hit can flinch',n=>rng(.05,()=>{const d=mon();hit(mon(n),d,'Pound');assert(data(d).flinch);}));
add('Sticky Hold','item theft fails while bearer remains conscious',n=>{const p=mon(),d=mon(n,{heldItem:'leftovers'});hit(p,d,'Thief');assert.equal(d.heldItem,'leftovers');assert(!p.heldItem);});
add('Sturdy','lethal damage at full HP leaves one',n=>{const p=mon(n);hit(mon(null,{level:999,currentAttack:9999,attack:9999}),p);assert.equal(p.currentHp,1);});
add('Suction Cups','phazing does not force a switch',n=>assert(!hit(mon(),mon(n),'Roar').forceSwitch));
add('Super Luck','critical hit threshold is raised',n=>rng(.07,()=>{assert(hit(mon(n),mon()).critical);assert(!hit(mon(),mon()).critical);}));
add('Synchronize','poison is reflected to the opponent',n=>{const p=mon(),d=mon(n);hit(p,d,'Toxic');assert.equal(p.status,'badly_poison');assert.equal(d.status,'badly_poison');});
add('Tangled Feet','confusion lowers incoming accuracy',n=>{const p=mon(n);data(p).confusionTurns=3;assert(a.getAbilityAccuracyMultiplier(mon(),p,e.getMoveByName('Pound'),state())<1);});
add('Tinted Lens','resisted attack damage is doubled',n=>assert(dmg(n,'Water Gun',{}, {type1:'Water'})>dmg(null,'Water Gun',{}, {type1:'Water'})));
add('Technician','low base power damage increases',n=>assert(dmg(n,'Pound')>dmg(null,'Pound')));
add('Trace','entry copies a copyable opponent ability',n=>{const p=mon(n);entry(p,mon('Guts'));assert.equal(p.passiveAbility,'Guts');});
add('Truant','every second action is skipped without spending PP',n=>{const p=mon(n),d=mon();assert(hit(p,d).success);const hp=d.currentHp;assert(!hit(p,d).success);assert.equal(d.currentHp,hp);assert(hit(p,d).success);});
add('Unaware','opposing offensive stages are ignored',n=>{const p=mon(),d=mon(n);e.applyStageChange(p,'attack',6,[],p);assert.equal(hit(p,d).damage,dmg(null,'Pound'));});
add('Unburden','losing a held item doubles Speed',n=>{const p=mon(n);data(p).unburden=true;assert.equal(e.getBattleSpeed(p),200);p.heldItem='leftovers';assert.equal(e.getBattleSpeed(p),100);});
add('Unnerve','opponent berry cannot activate',n=>{const d=mon(null,{heldItem:'sitrus_berry',currentHp:190});hit(mon(n),d);assert.equal(d.heldItem,'sitrus_berry');});
add('Wonder Guard','neutral damage fails but a weakness can hit',n=>{assert.equal(hit(mon(),mon(n)).damage,0);assert(hit(mon(),mon(n,{type1:'Grass'}),'Ember').damage>0);});
add('Wonder Skin','incoming status accuracy is capped at one half',n=>rng(.6,()=>{assert(hit(mon(),mon(n),'Toxic').missed);assert(!hit(mon(),mon(),'Toxic').missed);}));
add('Zen Mode','Darmanitan changes at half HP',n=>{const p=require('../../scripts/calibrateCorruptionRaids').make(555,50,1,['Pound'],n);p.currentHp=Math.floor(p.maxHp/2);forms.sync(p,'end');assert.equal(data(p).abilityForm,'Darmanitan-Zen');});
// These effects are field-only. Their behavioral contracts live in the native
// multi-actor test, rather than pretending that they benefit a lone Pokémon.
for(const n of ['Friend Guard','Healer','Minus','Plus','Telepathy','Illuminate','Honey Gather'])cases.set(n,{name:n,label:n==='Illuminate'||n==='Honey Gather'?'no in-battle modifier; overworld classified separately':'native multi-actor contract',nativeOnly:true});
module.exports={cases,mon,hit,end,entry,state,rng,data,stage};
